import type { ArgumentsCamelCase } from 'yargs';
import type { IConnector } from '@servicenow/sdk-api';
import type { ProgressOutcome } from './poller';
export type ParamType = 'string' | 'number' | 'boolean';
/**
 * Describes a single parameter shared between the CLI flag and the sn_cicd request payload.
 * A generic command builder turns each ParamSpec into a yargs option and a request field,
 * so a new sn_cicd operation only needs to declare its params instead of hand-writing a builder/handler.
 */
export interface ParamSpec {
    /** camelCase name. The CLI flag is derived as kebab-case (e.g. testSuiteSysId -> --test-suite-sys-id). */
    name: string;
    describe: string;
    type: ParamType;
    required?: boolean;
    default?: string | number | boolean;
    choices?: readonly string[];
    alias?: string;
    /** Field name sent to the sn_cicd API. Defaults to snake_case(name). */
    apiName?: string;
    /**
     * Where the value goes on the wire. Defaults to 'query' — every known sn_cicd operation
     * (testsuite/run, app_repo/install, app_repo/publish, tests/run_test) takes its parameters as
     * query string params, even on POST requests. Use 'body' only for an operation that's confirmed
     * to need an actual JSON request body. Use 'path' for a param that's only interpolated into
     * `CicdOperation.path` (e.g. a progress id) and shouldn't also be sent as a query/body field.
     * Use 'client' for a param that only exists to be consumed by `CicdOperation.resolve` (e.g. a
     * name that gets resolved to a sys_id) and should never be sent to the API directly.
     */
    location?: 'query' | 'body' | 'path' | 'client';
    /**
     * Names (camelCase, matching other params' `name`) of params this one is mutually exclusive
     * with. Enforced via `yargs.conflicts()` — passing both fails with a clear CLI error instead of
     * silently sending an ambiguous request.
     */
    conflicts?: string[];
}
/** Raw JSON body returned by the sn_cicd `result` envelope for a given operation. */
export type CicdResultBody = Record<string, unknown>;
/** Context passed to `CicdOperation.successMessage` to build the human-readable completion summary. */
export interface CicdSuccessContext {
    /** The initial dispatch response body, captured before polling (e.g. install's `rollback_version` lives here). */
    result: CicdResultBody;
    /** The polled progress outcome for operations that waited for completion. */
    progress: {
        successful: boolean;
        status: string;
        statusMessage: string;
        percentComplete: number;
    };
    /** The builder's default one-line summary (e.g. `Operation completed: Done`), to reuse or replace. */
    defaultMessage: string;
}
export type CicdArguments = ArgumentsCamelCase<Record<string, unknown>>;
/** Context passed to a `CicdOperation.postProcess` hook once `poll` has reached a terminal state. */
export interface PostProcessContext {
    connector: IConnector;
    /** The completed progress snapshot, including its raw `links` (e.g. `links.results`/`links.source`). */
    progress: ProgressOutcome;
    progressId: string;
}
/** Result of interpreting a fetched result record via a `CicdOperation.postProcess` hook. */
export interface CicdInterpretedResult {
    successful: boolean;
    /** Structured data to merge into the command's machine-readable output (e.g. resultId, testStatus). */
    summary: Record<string, unknown>;
    /**
     * Human-readable text for this outcome: printed after the completion headline on success, or
     * thrown as the error message on failure. Always optional — omitting it on failure falls back
     * to the tracker's own status message (or a generic one), but a specific message here is
     * usually far more informative.
     */
    displayMessage?: string;
}
/**
 * Declarative description of a single sn_cicd REST operation. A generic command builder
 * (see command-builder.ts) turns this into a yargs command — CLI flags, request construction,
 * and optional progress polling are all derived from this definition.
 */
export interface CicdOperation {
    /** Stable identifier used for telemetry, mirroring the sn_cicd URL segment, e.g. 'testsuite.run'. */
    id: string;
    /**
     * Optional group this operation is nested under, e.g. 'testsuite' makes the command
     * `now-sdk cicd testsuite <command>`. Operations that share a group are registered together as
     * subcommands of it — this is what disambiguates same-named leaves (testsuite `run` vs test `run`).
     * Omit it for operations that sit directly under `cicd` (e.g. install/publish/rollback); the CLI
     * layout is grouped by what's useful to developers, not mirrored onto the sn_cicd API's URL structure.
     */
    group?: string;
    /** The leaf command name under `cicd` (or under `group`, when set), e.g. 'run' or 'install'. */
    command: string;
    describe: string;
    method: 'GET' | 'POST';
    /** Request path, relative to the instance root. Can depend on parsed args (e.g. a path parameter). */
    path: string | ((args: CicdArguments) => string);
    params: ParamSpec[];
    /**
     * Whether a successful response should be followed by polling the generic sn_cicd progress
     * tracker (`/api/sn_cicd/progress/{id}`) to completion.
     */
    poll?: boolean;
    /**
     * Extracts the progress id to poll. Required when `poll` is true. Most operations derive it from
     * the initial response body (`result.links.progress.id`); operations that resume watching an
     * already-known progress id (e.g. `testsuite watch`) can instead read it from the parsed CLI args.
     */
    getProgressId?: (result: CicdResultBody, args: CicdArguments) => string | undefined;
    /**
     * Runs once `poll` reaches a terminal state, to enrich the outcome with more detail — e.g.
     * fetching `progress.links.results.id`'s result record (see `atf-results.ts`). Runs regardless
     * of `progress.successful`, so it has the option to override the tracker's own verdict.
     * Only meaningful with `poll: true`.
     */
    postProcess?: (ctx: PostProcessContext) => Promise<CicdInterpretedResult>;
    /**
     * Extra validation yargs' declarative options can't express (e.g. "at least one of these two
     * params is required"). Return `true` when valid, or an error message string to reject the
     * command before it runs.
     */
    check?: (args: CicdArguments) => true | string;
    /**
     * Optional hook to derive/resolve param values before the request is built — e.g. resolving a
     * human-friendly name to a sys_id via a Table API lookup (there's no server-side name param for
     * every sn_cicd operation, unlike `testsuite/run`). Runs after `check` validation, before
     * `extractParamPayload`/`getProgressId` see the args. Returning a value merges it
     * into `args` under that camelCase key; returning nothing leaves args untouched (e.g. when a
     * sys_id was already provided directly and there's nothing to resolve).
     */
    resolve?: (ctx: {
        connector: IConnector;
        args: CicdArguments;
    }) => Promise<Record<string, unknown> | void>;
    /**
     * Extra fields to attach to this operation's telemetry event (in addition to the `cicd.<id>` event
     * name), e.g. the scope/app sys_id being installed or published. Reads from `args` after `resolve`
     * has run, so resolved values (not just directly-provided ones) are available. Returning nothing
     * emits a name-only event, same as operations that don't define this hook.
     */
    telemetryData?: (args: CicdArguments) => Record<string, unknown> | undefined;
    /**
     * Optional per-operation override for the human-readable completion summary printed after a polled
     * operation finishes (non `--select`/`-o` output only). Given the finished `result`, the `progress`
     * outcome, and the builder's `defaultMessage`, return the line(s) to print — or `undefined` to fall
     * back to `defaultMessage`. Lets an operation surface something extra from its result that plain
     * human output would otherwise hide (e.g. install adds a "rollback available to version X" line from
     * `result.rollback_version`). Machine callers are unaffected — they read the field straight off the
     * envelope via `--select result.<field>`.
     */
    successMessage?: (ctx: CicdSuccessContext) => string | string[] | undefined;
}
